/** The "HE" brand mark, rebuilt as SVG from the logo geometry. */
function brand_mark(string $class = 'mark'): string
{
    return '<svg class="' . $class . '" viewBox="0 0 333 273" aria-hidden="true"><g fill="currentColor">'
        . '<rect class="m1" x="0" y="0" width="60" height="273"/>'
        . '<rect class="m2" x="166" y="0" width="60" height="273"/>'
        . '<rect class="m3" x="0" y="106" width="333" height="60"/>'
        . '<rect class="m4" x="237" y="0" width="96" height="59"/>'
        . '<rect class="m5" x="237" y="213" width="96" height="60"/>'
        . '</g></svg>';
}
